const payload = $input.first().json ?? {};
const workflow = payload.workflow ?? payload.data?.workflow ?? {};
const execution = payload.execution ?? payload.data?.execution ?? payload.executionData ?? {};
const error = execution.error ?? payload.error ?? payload.data?.error ?? {};

const redact = (value) => String(value ?? '')
  .replace(/(authorization\s*[:=]\s*bearer\s+)[^\s,;]+/gi, '$1[REDACTED]')
  .replace(/([?&](?:access_token|api_key|key|token)=)[^&\s]+/gi, '$1[REDACTED]')
  .replace(/(x-goog-api-key\s*[:=]\s*)[^\s,;]+/gi, '$1[REDACTED]')
  .replace(/([A-Za-z0-9_-]{32,})/g, '[REDACTED]');

const firstText = (...values) => {
  for (const value of values) {
    if (typeof value === 'string' && value.trim()) return value.trim();
    if (typeof value === 'number' && Number.isFinite(value)) return String(value);
  }
  return '';
};

const workflowName = redact(firstText(workflow.name, payload.workflowName) || 'nieznany workflow').slice(0, 180);
const workflowId = firstText(workflow.id, payload.workflowId) || 'unknown';
let executionId = firstText(execution.id, payload.executionId, payload.id);
const rawUrl = firstText(execution.url, payload.executionUrl, payload.url);
if (!executionId && rawUrl) {
  const match = /\/(?:executions?|workflow\/[^/]+)\/(\d+)(?:[/?#]|$)/.exec(rawUrl);
  if (match) executionId = match[1];
}
executionId = (executionId || 'unknown').slice(0, 100);

const nodeNameRaw = firstText(
  execution.lastNodeExecuted,
  execution.lastNode,
  error.node?.name,
  error.nodeName,
  payload.lastNodeExecuted,
  payload.node?.name,
  payload.nodeName,
);
const nodeName = redact(nodeNameRaw || 'brak danych wykonania od n8n').slice(0, 180);

const messageRaw = firstText(
  error.message,
  error.description,
  error.cause?.message,
  execution.message,
  payload.message,
  payload.errorMessage,
);
const payloadKeys = Object.keys(payload).sort().slice(0, 20).join(', ') || 'brak';
const executionKeys = execution && typeof execution === 'object'
  ? (Object.keys(execution).sort().slice(0, 20).join(', ') || 'brak')
  : 'brak';
const fallbackMessage = `n8n nie przekazał komunikatu błędu (payload: ${payloadKeys}; execution: ${executionKeys})`;
const message = redact(messageRaw || fallbackMessage).replace(/\s+/g, ' ').slice(0, 900);
const mode = redact(firstText(execution.mode, payload.mode) || 'production').slice(0, 50);
const url = /^https:\/\//.test(rawUrl) ? rawUrl.slice(0, 500) : '';

const state = $getWorkflowStaticData('global');
state.recent = state.recent && typeof state.recent === 'object' ? state.recent : {};
const now = Date.now();
const ttlMs = 10 * 60 * 1000;
for (const [key, storedAt] of Object.entries(state.recent)) {
  if (!Number.isFinite(Number(storedAt)) || now - Number(storedAt) > ttlMs) delete state.recent[key];
}
const fingerprint = `${workflowId}:${nodeName}:${message}`;
if (state.recent[fingerprint]) return [];
state.recent[fingerprint] = now;

// Hard memory bound: keep only the newest 256 fingerprints even during an alert storm.
const recentEntries = Object.entries(state.recent);
if (recentEntries.length > 256) {
  recentEntries
    .sort((a, b) => Number(a[1] || 0) - Number(b[1] || 0))
    .slice(0, recentEntries.length - 256)
    .forEach(([key]) => delete state.recent[key]);
}

const lines = [
  '🚨 **Virya automation failed**',
  `**Workflow:** ${workflowName}`,
  `**Node:** ${nodeName}`,
  `**Execution:** ${executionId} (${mode})`,
  `**Error:** ${message}`,
];
if (url) lines.push(`**Open:** ${url}`);
lines.push('Retry automatyczny pozostaje po stronie noda albo CrowdRelay outbox.');

return [{ json: {
  content: lines.join('\n').slice(0, 1900),
  workflow_id: workflowId.slice(0, 100),
  execution_id: executionId,
  fingerprint
} }];

